-- 급식 NEXT: Supabase PostgreSQL 초기 스키마
create extension if not exists pgcrypto;
create type public.meal_time as enum ('breakfast','lunch','dinner');
create type public.share_status as enum ('pending','approved','rejected','revoked','expired');
create type public.variable_type as enum ('number','boolean','single_select','multi_select');

create table public.schools (id uuid primary key default gen_random_uuid(), name text not null, school_code text unique not null, school_level text not null, province text not null, district text not null, student_count int not null check(student_count>=0), meal_target_count int not null check(meal_target_count>=0), male_count int not null default 0, female_count int not null default 0, gender_type text not null, boarding_type text not null, serves_breakfast boolean not null default false, serves_lunch boolean not null default true, serves_dinner boolean not null default false, latitude numeric, longitude numeric, created_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table public.school_members (school_id uuid references public.schools on delete cascade, user_id uuid references auth.users on delete cascade, role text not null default 'manager', primary key(school_id,user_id));
create table public.meal_categories (id smallserial primary key, name text unique not null);
create table public.standard_tags (id smallserial primary key, name text unique not null);
create table public.meal_records (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools on delete cascade, meal_date date not null, meal_time public.meal_time not null, target_count int not null check(target_count>0), menu_text text not null, weather_status text, temperature numeric, has_precipitation boolean not null default false, prepared_count int not null check(prepared_count>=0), actual_count int not null check(actual_count>=0), waste_kg numeric not null check(waste_kg>=0), private_note text, created_by uuid references auth.users, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index meal_records_school_date_idx on public.meal_records(school_id,meal_date);
create table public.meal_record_categories (meal_record_id uuid references public.meal_records on delete cascade, category_id smallint references public.meal_categories, primary key(meal_record_id,category_id));
create table public.meal_record_tags (meal_record_id uuid references public.meal_records on delete cascade, tag_id smallint references public.standard_tags, primary key(meal_record_id,tag_id));
create table public.custom_variable_templates (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools on delete cascade, name text not null, description text, input_type public.variable_type not null, unit text, applies_breakfast boolean default false, applies_lunch boolean default false, applies_dinner boolean default false, required boolean not null default false, use_for_prediction boolean not null default true, active boolean not null default true, created_at timestamptz not null default now(), unique(school_id,name));
create table public.custom_variable_options (id uuid primary key default gen_random_uuid(), template_id uuid not null references public.custom_variable_templates on delete cascade, label text not null, sort_order int not null default 0);
create table public.custom_variable_values (id uuid primary key default gen_random_uuid(), template_id uuid not null references public.custom_variable_templates on delete cascade, meal_record_id uuid not null references public.meal_records on delete cascade, number_value numeric, boolean_value boolean, text_value text, json_value jsonb, unique(template_id,meal_record_id));
create table public.data_share_requests (id uuid primary key default gen_random_uuid(), requester_school_id uuid not null references public.schools, provider_school_id uuid not null references public.schools, purpose text not null, requested_meal_times public.meal_time[] not null, message text, status public.share_status not null default 'pending', requested_by uuid references auth.users, created_at timestamptz not null default now(), decided_at timestamptz, check(requester_school_id<>provider_school_id));
create table public.data_share_permissions (id uuid primary key default gen_random_uuid(), request_id uuid unique not null references public.data_share_requests on delete cascade, granted_meal_times public.meal_time[] not null, data_start date not null, data_end date not null, valid_from timestamptz not null, valid_until timestamptz not null, max_records int not null check(max_records>0), allowed_custom_template_ids uuid[] not null default '{}', terms_accepted_at timestamptz, revoked_at timestamptz, revoked_by uuid references auth.users, created_at timestamptz not null default now(), check(data_start<=data_end), check(valid_from<valid_until));
create table public.external_dataset_blocks (id uuid primary key default gen_random_uuid(), permission_id uuid unique not null references public.data_share_permissions on delete cascade, requester_school_id uuid not null references public.schools, active boolean not null default false, deleted_at timestamptz, created_at timestamptz not null default now());
create table public.data_share_audit_logs (id bigint generated always as identity primary key, request_id uuid references public.data_share_requests, actor_school_id uuid references public.schools, action text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.predictions (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, prediction_date date not null, meal_time public.meal_time not null, target_count int not null, expected_count int not null, expected_rate numeric not null, lower_count int, upper_count int, confidence text, input_snapshot jsonb not null, created_by uuid references auth.users, created_at timestamptz not null default now());
create table public.prediction_references (prediction_id uuid references public.predictions on delete cascade, meal_record_id uuid references public.meal_records, source_type text not null check(source_type in('own','external')), similarity numeric not null, weight numeric not null, primary key(prediction_id,meal_record_id));

insert into public.meal_categories(name) values ('밥류'),('국·찌개류'),('육류'),('생선·해산물'),('면류'),('분식'),('채식'),('디저트'),('특별식'),('기타') on conflict do nothing;
insert into public.standard_tags(name) values ('시험'),('체험학습'),('체육대회'),('축제'),('방학 전후'),('학생 대회 참가'),('외출 인원 증가'),('결석 증가'),('운동부 경기'),('학교 행사'),('기타') on conflict do nothing;

alter table public.schools enable row level security; alter table public.school_members enable row level security; alter table public.meal_records enable row level security; alter table public.custom_variable_templates enable row level security; alter table public.data_share_requests enable row level security; alter table public.data_share_permissions enable row level security; alter table public.external_dataset_blocks enable row level security; alter table public.predictions enable row level security;
create function public.is_school_member(s uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from school_members where school_id=s and user_id=auth.uid()) $$;
create policy schools_member_read on public.schools for select using(public.is_school_member(id));
create policy members_self_read on public.school_members for select using(user_id=auth.uid());
create policy own_meals_all on public.meal_records for all using(public.is_school_member(school_id)) with check(public.is_school_member(school_id));
create policy own_templates_all on public.custom_variable_templates for all using(public.is_school_member(school_id)) with check(public.is_school_member(school_id));
create policy share_parties_read on public.data_share_requests for select using(public.is_school_member(requester_school_id) or public.is_school_member(provider_school_id));
create policy requester_create on public.data_share_requests for insert with check(public.is_school_member(requester_school_id));
create policy provider_update on public.data_share_requests for update using(public.is_school_member(provider_school_id));
create policy permission_parties_read on public.data_share_permissions for select using(exists(select 1 from data_share_requests r where r.id=request_id and (public.is_school_member(r.requester_school_id) or public.is_school_member(r.provider_school_id))));
create policy provider_permission_write on public.data_share_permissions for all using(exists(select 1 from data_share_requests r where r.id=request_id and public.is_school_member(r.provider_school_id))) with check(exists(select 1 from data_share_requests r where r.id=request_id and public.is_school_member(r.provider_school_id)));
create policy requester_blocks_all on public.external_dataset_blocks for all using(public.is_school_member(requester_school_id)) with check(public.is_school_member(requester_school_id));
create policy own_predictions_all on public.predictions for all using(public.is_school_member(school_id)) with check(public.is_school_member(school_id));

-- 운영 조회는 Edge Function/RPC에서 승인 상태, terms_accepted_at, 유효기간,
-- revoked_at, 블록 active/deleted_at, max_records를 모두 검증한 후 익명 필드만 반환한다.
-- private_note, created_by, 담당자 이메일과 학생 개인정보는 절대 공유하지 않는다.
